/**
 * SWM Dashboard: module accordions, Chart.js charts, ward-map heatmaps, To-month refresh.
 */
(function () {
    'use strict';

    var cfg = window.swmDashboardConfig || {};
    var ChartCtor = typeof window.Chart === 'function' ? window.Chart : null;
    var chartInstances = {};

    var palette = {
        bar: 'rgba(54, 162, 235, 0.75)',
        barHover: 'rgba(54, 162, 235, 0.9)',
        doughnut: [
            'rgba(54, 162, 235, 0.65)',
            'rgba(251, 176, 64, 0.85)',
            'rgba(153, 202, 60, 0.85)',
            'rgba(90, 155, 212, 0.65)',
            'rgba(255, 99, 132, 0.65)',
            'rgba(153, 102, 255, 0.65)',
        ],
    };

    function initModuleAccordions() {
        document.querySelectorAll('.swm-module-toggle').forEach(function (el) {
            el.addEventListener('click', function () {
                var section = el.closest('.dash-section');
                if (!section) {
                    return;
                }
                section.classList.toggle('collapsed');
                if (!section.classList.contains('collapsed')) {
                    initCharts();
                    initHeatmaps();
                    resizeHeatmapMaps();
                }
            });
        });
    }

    function scaleOptions(unitX, unitY) {
        var scales = {};
        if (unitX) {
            scales.xAxes = [{ scaleLabel: { display: true, labelString: unitX } }];
        }
        if (unitY) {
            scales.yAxes = [{ scaleLabel: { display: true, labelString: unitY }, ticks: { beginAtZero: true } }];
        }
        return scales;
    }

    function destroyChart(id) {
        if (chartInstances[id]) {
            chartInstances[id].destroy();
            delete chartInstances[id];
        }
    }

    function renderBar(canvas, chart) {
        var opts = chart.options || {};
        var ds = (chart.datasets && chart.datasets[0]) ? chart.datasets[0] : { data: [] };
        destroyChart(canvas.id);
        chartInstances[canvas.id] = new ChartCtor(canvas.getContext('2d'), {
            type: 'bar',
            data: {
                labels: chart.labels || [],
                datasets: [{
                    label: ds.label || '',
                    data: ds.data || [],
                    backgroundColor: palette.bar,
                    hoverBackgroundColor: palette.barHover,
                }],
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                legend: { display: false },
                scales: scaleOptions(opts.unitX, opts.unitY),
            },
        });
    }

    function renderDoughnut(canvas, chart) {
        var ds = (chart.datasets && chart.datasets[0]) ? chart.datasets[0] : { data: [] };
        var colors = palette.doughnut;
        destroyChart(canvas.id);
        chartInstances[canvas.id] = new ChartCtor(canvas.getContext('2d'), {
            type: 'doughnut',
            data: {
                labels: chart.labels || [],
                datasets: [{
                    data: ds.data || [],
                    backgroundColor: (chart.labels || []).map(function (_, i) {
                        return colors[i % colors.length];
                    }),
                }],
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                legend: { position: 'bottom' },
            },
        });
    }

    function initCharts() {
        if (!ChartCtor) {
            console.warn('SWM Dashboard: Chart.js is not loaded; charts were skipped.');
            return;
        }
        document.querySelectorAll('.swm-chart-canvas').forEach(function (canvas) {
            var raw = canvas.getAttribute('data-chart');
            if (!raw) {
                return;
            }
            var chart;
            try {
                chart = JSON.parse(raw);
            } catch (e) {
                return;
            }
            if (chart.type === 'doughnut') {
                renderDoughnut(canvas, chart);
            } else {
                renderBar(canvas, chart);
            }
        });
    }

    function heatmapColor(pct, alpha) {
        var p = Math.max(0, Math.min(100, pct));
        var r = Math.round(225 - (p / 100) * (225 - 23));
        var g = Math.round(240 - (p / 100) * (240 - 162));
        var b = Math.round(245 - (p / 100) * (245 - 184));
        if (alpha == null) {
            return 'rgb(' + r + ',' + g + ',' + b + ')';
        }
        return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
    }

    function buildWardValueMap(wards, values) {
        var map = {};
        wards.forEach(function (ward, i) {
            map[String(ward)] = values[i] != null ? Number(values[i]) : 0;
        });
        return map;
    }

    function parseMapExtent(bbox) {
        if (!bbox || typeof ol === 'undefined') {
            return null;
        }
        var parts = String(bbox).split(',').map(Number);
        if (parts.length !== 4 || parts.some(function (n) { return Number.isNaN(n); })) {
            return null;
        }
        return ol.proj.transformExtent(parts, 'EPSG:4326', 'EPSG:3857');
    }

    function resizeHeatmapMaps() {
        document.querySelectorAll('.swm-heatmap').forEach(function (el) {
            if (el._swmMap) {
                el._swmMap.updateSize();
            }
        });
    }

    function renderHeatmapFallbackGrid(el, chart) {
        var wards = chart.wards || [];
        var values = chart.values || [];
        var html = '<div class="heatmap-grid">';
        wards.forEach(function (ward, i) {
            var v = values[i] != null ? values[i] : 0;
            html += '<div class="heatmap-cell label">' + ward + '</div>';
            html += '<div class="heatmap-cell" style="background:' + heatmapColor(v) + '">' + v + '%</div>';
        });
        html += '</div>';
        var mapTarget = el.querySelector('.swm-ward-heatmap-map');
        if (mapTarget) {
            mapTarget.innerHTML = html;
        }
    }

    function fetchWardFeatures(mapCfg) {
        var workspace = mapCfg.workspace || '';
        var layerName = mapCfg.wardsLayer || 'wards_layer';
        var url = mapCfg.geoserverUrl + 'wfs'
            + '?service=WFS&version=1.0.0&request=GetFeature'
            + '&typeName=' + encodeURIComponent(workspace + ':' + layerName)
            + '&outputFormat=application/json'
            + '&authkey=' + encodeURIComponent(mapCfg.authKey || '');

        return fetch(url, { credentials: 'same-origin' }).then(function (r) {
            if (!r.ok) {
                throw new Error('WFS HTTP ' + r.status);
            }
            return r.json();
        });
    }

    function initWardHeatmapMap(el, chart, mapCfg) {
        var mapTarget = el.querySelector('.swm-ward-heatmap-map');
        var tooltip = el.querySelector('.swm-heatmap-tooltip');
        if (!mapTarget || typeof ol === 'undefined') {
            console.warn('SWM Dashboard: OpenLayers or map container missing; ward heatmap skipped.');
            renderHeatmapFallbackGrid(el, chart);
            return;
        }

        if (el.dataset.swmHeatmapInit === '1') {
            resizeHeatmapMaps();
            return;
        }

        if (!mapCfg.geoserverUrl || !mapCfg.workspace) {
            renderHeatmapFallbackGrid(el, chart);
            return;
        }

        var wardValues = buildWardValueMap(chart.wards || [], chart.values || []);
        var extent = parseMapExtent(mapCfg.bbox);

        fetchWardFeatures(mapCfg)
            .then(function (geojson) {
                var features = new ol.format.GeoJSON().readFeatures(geojson, {
                    dataProjection: 'EPSG:4326',
                    featureProjection: 'EPSG:3857',
                });

                var vectorSource = new ol.source.Vector({ features: features });
                var vectorLayer = new ol.layer.Vector({
                    source: vectorSource,
                    style: function (feature) {
                        var wardKey = String(feature.get('ward'));
                        var pct = wardValues[wardKey] != null ? wardValues[wardKey] : 0;
                        return new ol.style.Style({
                            fill: new ol.style.Fill({ color: heatmapColor(pct, 0.78) }),
                            stroke: new ol.style.Stroke({ color: '#ffffff', width: 1.2 }),
                        });
                    },
                });

                var wardsOutline = new ol.layer.Image({
                    source: new ol.source.ImageWMS({
                        url: mapCfg.geoserverUrl + 'wms',
                        params: {
                            LAYERS: (mapCfg.workspace || '') + ':' + (mapCfg.wardsLayer || 'wards_layer'),
                            TILED: true,
                            STYLES: 'wards_layer_none',
                        },
                        serverType: 'geoserver',
                    }),
                    opacity: 0.35,
                });

                var map = new ol.Map({
                    target: mapTarget,
                    layers: [wardsOutline, vectorLayer],
                    controls: ol.control.defaults({ attribution: false }),
                    interactions: ol.interaction.defaults({
                        altShiftDragRotate: false,
                        rotate: false,
                    }),
                    view: new ol.View({
                        minZoom: 10,
                        maxZoom: 19,
                    }),
                });

                if (extent) {
                    map.getView().fit(extent, { size: map.getSize(), padding: [16, 16, 16, 16] });
                } else {
                    var featureExtent = vectorSource.getExtent();
                    if (featureExtent.every(function (v) { return isFinite(v); })) {
                        map.getView().fit(featureExtent, { size: map.getSize(), padding: [16, 16, 16, 16] });
                    }
                }

                if (tooltip) {
                    map.on('pointermove', function (evt) {
                        var feature = map.forEachFeatureAtPixel(evt.pixel, function (f) { return f; });
                        if (!feature) {
                            tooltip.style.display = 'none';
                            return;
                        }
                        var wardKey = String(feature.get('ward'));
                        var pct = wardValues[wardKey] != null ? wardValues[wardKey] : 0;
                        tooltip.textContent = 'Ward ' + wardKey + ': ' + pct + '%';
                        tooltip.style.display = 'block';
                        tooltip.style.left = evt.pixel[0] + 12 + 'px';
                        tooltip.style.top = evt.pixel[1] + 12 + 'px';
                    });
                    map.getTargetElement().addEventListener('mouseleave', function () {
                        tooltip.style.display = 'none';
                    });
                }

                el._swmMap = map;
                el.dataset.swmHeatmapInit = '1';
                setTimeout(function () { map.updateSize(); }, 100);
            })
            .catch(function (err) {
                console.error('SWM Dashboard ward heatmap:', err);
                renderHeatmapFallbackGrid(el, chart);
            });
    }

    function initHeatmaps() {
        var mapCfg = cfg.map || {};

        document.querySelectorAll('.swm-heatmap').forEach(function (el) {
            var raw = el.getAttribute('data-heatmap');
            if (!raw) {
                return;
            }
            var chart;
            try {
                chart = JSON.parse(raw);
            } catch (e) {
                return;
            }
            initWardHeatmapMap(el, chart, mapCfg);
        });
    }

    function initExportButtons() {
        document.querySelectorAll('.swm-export-chart').forEach(function (btn) {
            btn.addEventListener('click', function () {
                var id = btn.getAttribute('data-target');
                var ch = chartInstances[id];
                if (!ch || !ch.canvas) {
                    return;
                }
                var link = document.createElement('a');
                link.download = (id || 'chart') + '.png';
                link.href = ch.canvas.toDataURL('image/png');
                link.click();
            });
        });
    }

    function refreshDashboard(toMonth) {
        var url = new URL(cfg.dataUrl, window.location.href);
        if (toMonth) {
            url.searchParams.set('to_month', toMonth);
        }
        if (typeof window.displayAjaxLoader === 'function') {
            window.displayAjaxLoader('');
        }
        return fetch(url.toString(), {
            headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
            credentials: 'same-origin',
        })
            .then(function (r) {
                if (!r.ok) {
                    throw new Error('HTTP ' + r.status);
                }
                return r.json();
            })
            .then(function () {
                window.location.href = url.pathname + '?to_month=' + encodeURIComponent(toMonth || '');
            })
            .catch(function (err) {
                console.error(err);
                if (typeof window.Swal !== 'undefined') {
                    window.Swal.fire({ icon: 'error', title: 'Error', text: 'Could not refresh dashboard.' });
                }
            })
            .finally(function () {
                if (typeof window.removeAjaxLoader === 'function') {
                    window.removeAjaxLoader();
                }
            });
    }

    function bindFilterForm() {
        var form = document.getElementById('swm-dashboard-filter-form');
        if (!form) {
            return;
        }
        form.addEventListener('submit', function (e) {
            e.preventDefault();
            var toMonth = document.getElementById('to_month').value;
            refreshDashboard(toMonth);
        });
    }

    function init() {
        initModuleAccordions();
        initCharts();
        initHeatmaps();
        initExportButtons();
        bindFilterForm();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
